## 5. Mesmo exemplo em React (como é no mercado)

```jsx
import { useState, useEffect } from "react";

export default function App() {
  const [tarefas, setTarefas] = useState(() =>
    JSON.parse(localStorage.getItem("tarefas") || "[]")
  );
  const [texto, setTexto] = useState("");

  useEffect(() => {
    localStorage.setItem("tarefas", JSON.stringify(tarefas));
  }, [tarefas]);

  function adicionar(e) {
    e.preventDefault();

    if (!texto.trim()) return;
    setTarefas([...tarefas, { id: crypto.randomUUID(), texto, feita: false }]);
    setTexto("");
  }

  function alternar(id) {
    setTarefas(tarefas.map(t => t.id === id ? { ...t, feita: !t.feita } : t));
  }

  function remover(id) {
    setTarefas(tarefas.filter(t => t.id !== id));
  }

  return (
    <main className="container">
      <h1>Minhas Tarefas</h1>
      <form onSubmit={adicionar}>
        <input value={texto} onChange={e => setTexto(e.target.value)} placeholder="Digite uma tarefa..." />
        <button type="submit">Adicionar</button>
      </form>
      <ul>
        {tarefas.map(t => (
          <li key={t.id} className={t.feita ? "feita" : ""}>
            <span onClick={() => alternar(t.id)}>{t.texto}</span>
            <button onClick={() => remover(t.id)}>X</button>
          </li>
        ))}
      </ul>
    </main>
  );
}
```

Para criar o projeto:
```bash
npm create vite@latest meu-app -- --template react-ts
cd meu-app
npm install
npm run dev
```

