```javascript
const form = document.getElementById("form-tarefa");
const input = document.getElementById("input-tarefa");
const lista = document.getElementById("lista-tarefas");

let tarefas = JSON.parse(localStorage.getItem("tarefas")) || [];

function salvar() {
  localStorage.setItem("tarefas", JSON.stringify(tarefas));
}

function render() {
  lista.innerHTML = "";

  tarefas.forEach((tarefa, indice) => {
    const li = document.createElement("li");
    if (tarefa.feita) li.classList.add("feita");

    const texto = document.createElement("span");
    texto.textContent = tarefa.texto; // textContent evita injeção de HTML (XSS)
    texto.addEventListener("click", () => {
      tarefas[indice].feita = !tarefas[indice].feita;
      salvar();
      render();
    });

    const remover = document.createElement("button");
    remover.textContent = "X";
    remover.addEventListener("click", () => {
      tarefas.splice(indice, 1);
      salvar();
      render();
    });

    li.append(texto, remover);
    lista.appendChild(li);
  });
}

form.addEventListener("submit", (evento) => {
  evento.preventDefault();
  const texto = input.value.trim();
  if (!texto) return;

  tarefas.push({ texto, feita: false });

  salvar();
  render();
  input.value = "";
});

render();
```

