## 4. Exemplo Prático Completo: As 3 Partes Essenciais em Ação

Para você ver exatamente como **Estrutura (HTML)**, **Estilo (CSS)** e **Comportamento/Estado/Rede (JavaScript)** se conectam na prática, abaixo está um componente funcional completo de um **Cartão de Consulta de Usuário** que simula uma busca no servidor, trata carregamento e atualiza a tela dinamicamente:

```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Exemplo Prático de Frontend</title>

  <!-- 2. CAMADA DE APRESENTAÇÃO (CSS) -->
  <style>
    :root {
      --cor-primaria: #2563eb;
      --cor-fundo: #f8fafc;
      --cor-texto: #1e293b;
    }

    body {
      font-family: system-ui, -apple-system, sans-serif;
      background-color: var(--cor-fundo);
      color: var(--cor-texto);
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
      margin: 0;
    }

    .card {
      background: white;
      padding: 24px;
      border-radius: 12px;
      box-shadow: 0 4px 15px rgba(0, 0, 0, 0.08);
      width: 100%;
      max-width: 360px;
      text-align: center;
    }

    .status-badge {
      display: inline-block;
      padding: 6px 12px;
      border-radius: 999px;
      font-size: 0.85rem;
      font-weight: 600;
      background-color: #e2e8f0;
      margin-bottom: 16px;
    }

    button {
      background-color: var(--cor-primaria);
      color: white;
      border: none;
      padding: 12px 20px;
      border-radius: 8px;
      font-size: 1rem;
      font-weight: 600;
      cursor: pointer;
      width: 100%;
      transition: opacity 0.2s;
    }

    button:disabled {
      opacity: 0.6;
      cursor: not-allowed;
    }
  </style>
</head>
<body>

  <!-- 1. CAMADA DE ESTRUTURA E SEMÂNTICA (HTML) -->
  <main class="card" aria-live="polite">
    <span id="badgeEstado" class="status-badge">Aguardando ação</span>
    <h1 id="nomeUsuario">Nenhum perfil carregado</h1>
    <p id="cargoUsuario">Clique no botão abaixo para buscar os dados no servidor.</p>

    <button id="btnBuscar" type="button">
      Carregar Perfil do Servidor
    </button>
  </main>

  <!-- 3. CAMADA DE COMPORTAMENTO, ESTADO E COMUNICAÇÃO (JAVASCRIPT) -->
  <script>
    // Mapeamento dos elementos da árvore DOM
    const btnBuscar = document.getElementById('btnBuscar');
    const badgeEstado = document.getElementById('badgeEstado');
    const nomeUsuario = document.getElementById('nomeUsuario');
    const cargoUsuario = document.getElementById('cargoUsuario');

    // Estado interno da aplicação (State Management simples)
    let carregando = false;

    // Simulação de uma chamada de API ao Backend (Assíncrona)
    function buscarDadosNoBackend() {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve({
            nome: "Ana Silva",
            cargo: "Engenheira de Software Full Stack",
            status: "Online • Dados sincronizados"
          });
        }, 1200); // Simula 1.2 segundos de tempo de resposta da rede
      });
    }

    // Evento de clique (Interatividade)
    btnBuscar.addEventListener('click', async () => {
      if (carregando) return;

      // 1. Atualiza o estado para "Carregando" (Feedback visual imediato)
      carregando = true;
      btnBuscar.disabled = true;
      btnBuscar.textContent = "Conectando ao Backend...";
      badgeEstado.textContent = "Sincronizando...";

      try {
        // 2. Faz a requisição assíncrona de dados
        const dados = await buscarDadosNoBackend();

        // 3. Renderiza os dados recebidos na interface (Manipulação do DOM)
        nomeUsuario.textContent = dados.nome;
        cargoUsuario.textContent = dados.cargo;
        badgeEstado.textContent = dados.status;
        badgeEstado.style.backgroundColor = "#dcfce7";
        badgeEstado.style.color = "#166534";
        btnBuscar.textContent = "Atualizar Dados";
      } catch (erro) {
        // 4. Tratamento de erro caso a rede falhe
        badgeEstado.textContent = "Erro de conexão";
        cargoUsuario.textContent = "Não foi possível carregar os dados.";
      } finally {
        carregando = false;
        btnBuscar.disabled = false;
      }
    });
  </script>
</body>
</html>
```

