### 5. Na Prática: Como as Partes Funcionam Juntas (Do Zero ao Mercado)

Vamos construir o mesmo módulo prático — um **Painel de Controle de Despesas** que valida dados, conversa com uma API e evita vulnerabilidades — de duas formas: primeiro com a **Tríade Pura (HTML + CSS + JS)** e depois como fazemos em empresas com **React + TypeScript**.

#### 5.1. Implementação 1: A Base Pura (HTML5 + CSS3 + JavaScript ES6+)
Salve o código abaixo como `index.html` e abra em qualquer navegador. Ele aplica semântica correta (`<form>`, `<label>`), layout responsivo, proteção contra XSS e simulação de envio `POST` assíncrono:

```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Controle Financeiro — Frontend Puro</title>

  <!-- CAMADA 2: APRESENTAÇÃO E RESPONSIVIDADE (CSS3) -->
  <style>
    :root {
      --primaria: #2563eb;
      --primaria-hover: #1d4ed8;
      --fundo: #f1f5f9;
      --card: #ffffff;
      --texto: #0f172a;
      --borda: #cbd5e1;
      --sucesso: #16a34a;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; }

    body {
      font-family: system-ui, -apple-system, sans-serif;
      background-color: var(--fundo);
      color: var(--texto);
      padding: 1.5rem;
      display: flex;
      justify-content: center;
    }

    .container {
      width: 100%;
      max-width: 520px;
      background: var(--card);
      padding: 1.5rem;
      border-radius: 12px;
      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.06);
    }

    h1 { font-size: 1.4rem; margin-bottom: 1rem; }

    .form-grid {
      display: grid;
      grid-template-columns: 1fr 130px;
      gap: 0.75rem;
      margin-bottom: 1rem;
    }

    /* Responsividade Mobile-First para telas pequenas */
    @media (max-width: 480px) {
      .form-grid { grid-template-columns: 1fr; }
    }

    .campo { display: flex; flex-direction: column; gap: 0.25rem; }
    label { font-size: 0.85rem; font-weight: 600; }

    input {
      padding: 0.65rem;
      border: 1px solid var(--borda);
      border-radius: 8px;
      font-size: 0.95rem;
    }

    button {
      grid-column: 1 / -1;
      padding: 0.75rem;
      background: var(--primaria);
      color: #fff;
      border: none;
      border-radius: 8px;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s;
    }

    button:hover:not(:disabled) { background: var(--primaria-hover); }
    button:disabled { opacity: 0.6; cursor: wait; }

    .resumo {
      display: flex;
      justify-content: space-between;
      padding: 0.75rem;
      background: #f8fafc;
      border-radius: 8px;
      font-weight: 600;
      margin-bottom: 1rem;
    }

    ul { list-style: none; }
    li {
      display: flex;
      justify-content: space-between;
      padding: 0.65rem 0;
      border-bottom: 1px solid #e2e8f0;
    }
    .valor-item { font-weight: 600; color: var(--sucesso); }
  </style>
</head>
<body>

  <!-- CAMADA 1: ESTRUTURA SEMÂNTICA E ACESSÍVEL (HTML5) -->
  <main class="container">
    <h1>Controle de Despesas</h1>

    <form id="form-despesa" class="form-grid">
      <div class="campo">
        <label for="input-descricao">Descrição</label>
        <input id="input-descricao" type="text" placeholder="Ex: Internet Fibra" required />
      </div>

      <div class="campo">
        <label for="input-valor">Valor (R$)</label>
        <input id="input-valor" type="number" step="0.01" min="0.01" placeholder="99.90" required />
      </div>

      <button id="btn-salvar" type="submit">Cadastrar Despesa</button>
    </form>

    <section class="resumo" aria-live="polite">
      <span>Total acumulado:</span>
      <span id="total-geral">R$ 0,00</span>
    </section>

    <ul id="lista-despesas"></ul>
  </main>

  <!-- CAMADA 3: COMPORTAMENTO, ESTADO E COMUNICAÇÃO DE REDE (JAVASCRIPT) -->
  <script>
    const form = document.getElementById('form-despesa');
    const inputDescricao = document.getElementById('input-descricao');
    const inputValor = document.getElementById('input-valor');
    const btnSalvar = document.getElementById('btn-salvar');
    const listaEl = document.getElementById('lista-despesas');
    const totalEl = document.getElementById('total-geral');

    // Estado da Aplicação (State Management em memória)
    const estado = {
      despesas: [],
      salvando: false
    };

    // Simula uma chamada HTTP POST para uma API Backend (ex: Spring Boot / Node.js)
    async function enviarParaApiBackend(novaDespesa) {
      return new Promise((resolve) => {
        setTimeout(() => {
          resolve({ id: crypto.randomUUID(), ...novaDespesa });
        }, 500); // Simula latência de 500ms na rede
      });
    }

    // Função de Renderização (Sincroniza o Estado com o DOM de forma segura contra XSS)
    function renderizarInterface() {
      listaEl.innerHTML = '';
      let soma = 0;

      estado.despesas.forEach((item) => {
        soma += item.valor;

        const li = document.createElement('li');
        const spanDesc = document.createElement('span');
        const spanVal = document.createElement('span');

        // textContent impede injeção de código malicioso (XSS)
        spanDesc.textContent = item.descricao;
        spanVal.textContent = item.valor.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
        spanVal.className = 'valor-item';

        li.append(spanDesc, spanVal);
        listaEl.appendChild(li);
      });

      totalEl.textContent = soma.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
    }

    // Escuta o evento de envio do formulário
    form.addEventListener('submit', async (evento) => {
      evento.preventDefault(); // Impede a página de recarregar
      if (estado.salvando) return;

      const descricao = inputDescricao.value.trim();
      const valor = parseFloat(inputValor.value);
      if (!descricao || isNaN(valor) || valor <= 0) return;

      try {
        // 1. Estado de Loading
        estado.salvando = true;
        btnSalvar.disabled = true;
        btnSalvar.textContent = 'Salvando no servidor...';

        // 2. Comunicação Assíncrona com o Backend
        const despesaSalva = await enviarParaApiBackend({ descricao, valor });

        // 3. Atualiza Estado e Interface
        estado.despesas.push(despesaSalva);
        renderizarInterface();
        form.reset();
        inputDescricao.focus();
      } catch (erro) {
        console.error('Falha na comunicação com a API:', erro);
      } finally {
        estado.salvando = false;
        btnSalvar.disabled = false;
        btnSalvar.textContent = 'Cadastrar Despesa';
      }
    });
  </script>
</body>
</html>
```

