#### 5.2. Implementação 2: Como fazemos no Mercado Corporativo (React + TypeScript)
Veja como o mesmo sistema fica mais enxuto, tipado e escalável usando **TypeScript + React**. Aqui você não manipula o DOM manualmente (`document.createElement`); você apenas altera o **Estado** e o React desenha a tela automaticamente:

```tsx
import { useState, FormEvent } from "react";

// 1. Contrato de Dados fortemente tipado com TypeScript
interface Despesa {
  id: string;
  descricao: string;
  valor: number;
}

export default function PainelFinanceiro() {
  const [despesas, setDespesas] = useState<Despesa[]>([]);
  const [descricao, setDescricao] = useState("");
  const [valor, setValor] = useState("");
  const [carregando, setCarregando] = useState(false);

  const totalAcumulado = despesas.reduce((acc, item) => acc + item.valor, 0);

  async function adicionarDespesa(e: FormEvent) {
    e.preventDefault();
    const valorNumerico = parseFloat(valor);
    if (!descricao.trim() || isNaN(valorNumerico) || valorNumerico <= 0) return;

    setCarregando(true);
    try {
      // Exemplo real de chamada HTTP POST para um Backend (ex: API em http://localhost:8080/api/despesas)
      const novaDespesa: Despesa = {
        id: crypto.randomUUID(),
        descricao: descricao.trim(),
        valor: valorNumerico,
      };

      setDespesas((listaAtual) => [...listaAtual, novaDespesa]);
      setDescricao("");
      setValor("");
    } finally {
      setCarregando(false);
    }
  }

  return (
    <main className="container">
      <h1>Controle de Despesas (React + TS)</h1>

      <form onSubmit={adicionarDespesa} className="form-grid">
        <input
          type="text"
          value={descricao}
          onChange={(e) => setDescricao(e.target.value)}
          placeholder="Descrição da despesa"
          required
        />
        <input
          type="number"
          step="0.01"
          value={valor}
          onChange={(e) => setValor(e.target.value)}
          placeholder="Valor (R$)"
          required
        />
        <button type="submit" disabled={carregando}>
          {carregando ? "Sincronizando..." : "Cadastrar Despesa"}
        </button>
      </form>

      <div className="resumo">
        <span>Total:</span>
        <strong>
          {totalAcumulado.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
        </strong>
      </div>

      <ul>
        {despesas.map((item) => (
          <li key={item.id}>
            <span>{item.descricao}</span>
            <strong>
              {item.valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
            </strong>
          </li>
        ))}
      </ul>
    </main>
  );
}
```

