  <!-- =========================================================
       CAMADA 3, 4 e 5: COMPORTAMENTO, ESTADO E REDE (JAVASCRIPT)
       ========================================================= -->
  <script>
    const API_URL = "http://localhost:9090/despesas";

    // Referências da Árvore DOM
    const form = document.getElementById("form-despesa");
    const inputDesc = document.getElementById("descricao");
    const inputValor = document.getElementById("valor");
    const selectCat = document.getElementById("categoria");
    const btnCadastrar = document.getElementById("btn-cadastrar");
    const statusRede = document.getElementById("status-rede");
    const listaEl = document.getElementById("lista-despesas");
    const totalEl = document.getElementById("total-acumulado");

    // 4. Gerenciamento de Estado (Inicializa do LocalStorage como cache seguro)
    let estadoDespesas = JSON.parse(localStorage.getItem("despesas_app")) || [];
    let carregando = false;

    function salvarCacheLocal() {
      localStorage.setItem("despesas_app", JSON.stringify(estadoDespesas));
    }

    function atualizarBadgeStatus(texto, corFundo, corTexto) {
      statusRede.textContent = texto;
      statusRede.style.backgroundColor = corFundo;
      statusRede.style.color = corTexto;
    }

    // 5. Comunicação de Rede (Tenta enviar via HTTP POST para o Backend; se offline, usa fallback local)
    async function salvarNoBackend(novaDespesa) {
      try {
        const resposta = await fetch(API_URL, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(novaDespesa)
        });

        if (!resposta.ok) throw new Error("Erro HTTP: " + resposta.status);
        const dadosSalvos = await resposta.json();
        atualizarBadgeStatus("Sincronizado com API", "#dcfce7", "#166534");
        return dadosSalvos;
      } catch (erroRede) {
        // Caso o servidor Backend (porta 9090) não esteja ligado, salva localmente após simular 400ms
        await new Promise((r) => setTimeout(r, 400));
        atualizarBadgeStatus("Modo Local (API Offline)", "#fef9c3", "#854d0e");
        return { id: crypto.randomUUID(), ...novaDespesa };
      }
    }

    // Renderização Segura (Usa textContent para blindar contra ataques XSS)
    function renderizarTela() {
      listaEl.innerHTML = "";
      let somaTotal = 0;

      estadoDespesas.forEach((item) => {
        somaTotal += item.valor;

        const li = document.createElement("li");
        li.className = "item-despesa";

        const divInfo = document.createElement("div");
        divInfo.className = "item-info";

        const strongDesc = document.createElement("strong");
        strongDesc.textContent = item.descricao; // Seguro contra XSS

        const spanCat = document.createElement("span");
        spanCat.className = "item-categoria";
        spanCat.textContent = item.categoria;

        divInfo.append(strongDesc, spanCat);

        const divAcoes = document.createElement("div");
        divAcoes.className = "item-acoes";

        const spanValor = document.createElement("span");
        spanValor.className = "valor-monetario";
        spanValor.textContent = item.valor.toLocaleString("pt-BR", {
          style: "currency",
          currency: "BRL"
        });

        const btnRemover = document.createElement("button");
        btnRemover.className = "btn-remover";
        btnRemover.textContent = "Excluir";
        btnRemover.addEventListener("click", () => {
          estadoDespesas = estadoDespesas.filter((d) => d.id !== item.id);
          salvarCacheLocal();
          renderizarTela();
        });

        divAcoes.append(spanValor, btnRemover);
        li.append(divInfo, divAcoes);
        listaEl.appendChild(li);
      });

      totalEl.textContent = somaTotal.toLocaleString("pt-BR", {
        style: "currency",
        currency: "BRL"
      });
    }

    // Evento de Submissão tratando os 4 Estados Assíncronos (Idle -> Loading -> Success/Error)
    form.addEventListener("submit", async (evento) => {
      evento.preventDefault();
      if (carregando) return;

      const descricao = inputDesc.value.trim();
      const valor = parseFloat(inputValor.value);
      const categoria = selectCat.value;

      if (!descricao || isNaN(valor) || valor <= 0) return;

      // Estado: LOADING
      carregando = true;
      btnCadastrar.disabled = true;
      btnCadastrar.textContent = "Enviando dados...";
      atualizarBadgeStatus("Sincronizando...", "#dbeafe", "#1e40af");

      try {
        const despesaCriada = await salvarNoBackend({ descricao, valor, categoria });
        estadoDespesas.push(despesaCriada);
        salvarCacheLocal();
        renderizarTela();
        form.reset();
        inputDesc.focus();
      } finally {
        carregando = false;
        btnCadastrar.disabled = false;
        btnCadastrar.textContent = "Cadastrar Despesa";
      }
    });

    // Inicializa a interface ao abrir a página
    renderizarTela();
  </script>
</body>
</html>
```

