<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Sistema Financeiro — Frontend Profissional</title>

  <!-- =========================================================
       CAMADA 2: APRESENTAÇÃO, LAYOUT E RESPONSIVIDADE (CSS3)
