### 5.2. Exemplo 2: O Padrão de Mercado com React + TypeScript
Em projetos profissionais, criamos a aplicação usando o **Vite** no terminal:
```bash
npm create vite@latest controle-financeiro -- --template react-ts
cd controle-financeiro
npm install
npm run dev
```

Veja como o código do componente `src/App.tsx` fica fortemente tipado, declarativo e limpo com **React + TypeScript**:

```tsx
import { useState, useEffect, FormEvent } from "react";

// 1. Contrato de Dados (Interface TypeScript que espelha a entidade do Backend)
export interface Despesa {
  id: string;
  descricao: string;
  valor: number;
  categoria: string;
}

export default function App() {
  const [despesas, setDespesas] = useState<Despesa[]>(() => {
    const salvo = localStorage.getItem("despesas_react");
    return salvo ? JSON.parse(salvo) : [];
  });

  const [descricao, setDescricao] = useState("");
  const [valor, setValor] = useState("");
  const [categoria, setCategoria] = useState("Moradia");
  const [carregando, setCarregando] = useState(false);
  const [erro, setErro] = useState<string | null>(null);

  // Sincroniza automaticamente o estado com o LocalStorage
  useEffect(() => {
    localStorage.setItem("despesas_react", JSON.stringify(despesas));
  }, [despesas]);

  const totalAcumulado = despesas.reduce((acc, item) => acc + item.valor, 0);

  async function handleCadastrar(e: FormEvent) {
    e.preventDefault();
    const valorNum = parseFloat(valor);
    if (!descricao.trim() || isNaN(valorNum) || valorNum <= 0) return;

    setCarregando(true);
    setErro(null);

    try {
      const novaDespesa: Despesa = {
        id: crypto.randomUUID(),
        descricao: descricao.trim(),
        valor: valorNum,
        categoria,
      };

      setDespesas((atual) => [...atual, novaDespesa]);
      setDescricao("");
      setValor("");
    } catch (err) {
      setErro("Não foi possível salvar a despesa.");
    } finally {
      setCarregando(false);
    }
  }

  function handleRemover(id: string) {
    setDespesas((atual) => atual.filter((item) => item.id !== id));
  }

  return (
    <main className="app-container">
      <h1>Controle Financeiro (React + TypeScript)</h1>

      {erro && <p role="alert" style={{ color: "#b91c1c" }}>{erro}</p>}

      <form onSubmit={handleCadastrar} className="form-grid">
        <input
          type="text"
          value={descricao}
          onChange={(e) => setDescricao(e.target.value)}
          placeholder="Descrição da despesa"
          required
        />
        <input
          type="number"
          step="0.01"
          value={valor}
          onChange={(e) => setValor(e.target.value)}
          placeholder="Valor (R$)"
          required
        />
        <select value={categoria} onChange={(e) => setCategoria(e.target.value)}>
          <option value="Moradia">Moradia</option>
          <option value="Alimentação">Alimentação</option>
          <option value="Estudos">Estudos</option>
          <option value="Transporte">Transporte</option>
        </select>

        <button type="submit" disabled={carregando}>
          {carregando ? "Salvando..." : "Cadastrar Despesa"}
        </button>
      </form>

      <section className="painel-resumo">
        <span>Total:</span>
        <strong>
          {totalAcumulado.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
        </strong>
      </section>

      <ul>
        {despesas.map((item) => (
          <li key={item.id} className="item-despesa">
            <div>
              <strong>{item.descricao}</strong> ({item.categoria})
            </div>
            <div>
              <span>
                {item.valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}
              </span>
              <button type="button" onClick={() => handleRemover(item.id)}>
                Excluir
              </button>
            </div>
          </li>
        ))}
      </ul>
    </main>
  );
}
```

