### 5.3. A Conexão Full Stack: Como o Backend (Java Spring Boot) Recebe Esse Frontend
Para fechar o entendimento de ponta a ponta, veja como um Controller em **Java (Spring Boot)** recebe exatamente o pacote `JSON` enviado pelo `fetch` do nosso Frontend acima:

```java
package br.com.financeiro.controller;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.util.List;

@RestController
@RequestMapping("/despesas")
@CrossOrigin(origins = "http://localhost:5173") // Libera o CORS para o servidor Vite do Frontend
public class DespesaController {

    private final DespesaService service;

    public DespesaController(DespesaService service) {
        this.service = service;
    }

    @GetMapping
    public ResponseEntity<List<DespesaDTO>> listarTodas() {
        return ResponseEntity.ok(service.listarTodas());
    }

    @PostMapping
    public ResponseEntity<DespesaDTO> cadastrar(@Valid @RequestBody DespesaDTO novaDespesa) {
        // O Backend realiza a validação definitiva e salva no MySQL/PostgreSQL
        DespesaDTO salva = service.salvarNoBanco(novaDespesa);
        return ResponseEntity.status(HttpStatus.CREATED).body(salva);
    }
}
